import { getRunMode, getCurrentNode, getRunLength, getRunNodes, RANKS } from './engine.js?v=6.4.0';
import { RANK_EFFECTS_NOT_MODELLED } from './classic-flow.js?v=6.4.0';
import { resolveEquipment, getEquipmentArtPath, CHARACTERS } from './data.js?v=6.4.0';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const modes=[{id:'standard',name:'标准博弈',tag:'经营 · 构筑 · 三个位面',desc:'完整经历招募、投资、补给与遭遇战。在三个首领之间经营利息、扩充团队，逐步完成阵容。',mark:'◇',features:['三个位面 · 23 个节点','保留利息与连胜收益','投资环境影响整局运营']},{id:'overclock',name:'超频博弈',tag:'快节奏 · 高资源',desc:'每个位面的节点更少，每个节点的金币与经验更多。利息不再生效，更快形成高星、高人口阵容。',mark:'ϟ',features:['三个位面 · 16 个节点','更多金币与经验 · 无利息','每个位面保留投资、补给与首领']}];
export function modeScreen(game,selected='standard',difficulty=0,fresh=false){
 return `<div class="reference-overlay"><section class="reference-fullscreen run-mode-screen" role="dialog" aria-modal="true" aria-labelledby="modal-heading"><div class="run-mode-grid" aria-hidden="true"></div><header><small>货币战争 · 零和博弈</small><h1 id="modal-heading">选择博弈模式</h1><p>构筑你的阵容，迎接新的投资机会。</p></header>${!fresh?'<button class="run-return" data-action="close">← 返回当前对局</button>':''}<div class="run-modes">${modes.map(m=>`<button data-action="mode-select" data-mode="${m.id}" class="run-mode-card ${selected===m.id?'selected':''}" aria-pressed="${selected===m.id}"><span class="run-mode-symbol">${m.mark}</span><small>${m.tag}</small><h2>${m.name}</h2><p>${m.desc}</p><ul>${m.features.map(f=>`<li>${f}</li>`).join('')}</ul><span class="run-mode-check">${selected===m.id?'✓ 已选择':'选择模式'}</span></button>`).join('')}</div><div class="run-difficulty run-ranks" role="group" aria-label="挑战职级"><span>挑战职级</span>${RANKS.map(r=>`<button data-action="rank-select" data-index="${r.id}" aria-pressed="${difficulty===r.id}" class="${difficulty===r.id?'selected':''}" title="${r.name}"><b>${r.abbr}</b><small>${r.name}</small></button>`).join('')}</div><div class="run-rank-effects"><strong>${RANKS[difficulty]?.abbr||'A0'} ${RANKS[difficulty]?.name||'黑铁'} · 生效的职级规则</strong><ul>${RANKS.filter(r=>r.id<=difficulty).flatMap(r=>r.effects.filter(e=>!RANK_EFFECTS_NOT_MODELLED.has(e)).map(e=>`<li><b>${r.abbr}</b>${e}</li>`)).join('')}</ul>${RANKS.some(r=>r.id<=difficulty&&r.effects.some(e=>RANK_EFFECTS_NOT_MODELLED.has(e)))?`<p class="run-rank-off">本作未模拟：${[...new Set(RANKS.filter(r=>r.id<=difficulty).flatMap(r=>r.effects.filter(e=>RANK_EFFECTS_NOT_MODELLED.has(e)).map(e=>/词缀/.test(e)?'敌人随机词缀':/星级/.test(e)?'敌人星级提升':/狂化/.test(e)?'狂化节点':'投资策略提升敌人难度')))].join('、')}</p>`:''}</div><p class="run-mode-note">职级规则来自旧版客户端；敌人强度按职级分为三档网页适配（A0–A2 / A3–A5 / A6–A8）。</p><button class="reference-confirm-button" data-action="start-run">开始${modes.find(m=>m.id===selected)?.name||'标准博弈'}</button>${!fresh?'<p class="run-replace-note">开始新局会替换当前对局；返回可继续已有进度。</p>':''}<span class="reference-screen-signature">经典回响 · 非官方同人</span></section></div>`;
}
const rewardArt=r=>r.kind==='character'?`<img src="assets/portraits/${esc(r.id)}.png" alt="${esc(CHARACTERS.find(c=>c.id===r.id)?.name||'角色')}">`:r.kind==='item'&&resolveEquipment(r.id)?`<img src="${getEquipmentArtPath(r.id)}" alt="${esc(resolveEquipment(r.id).name)}">`:r.kind==='chest'?`<img src="assets/loot/chest-${r.quality||'basic'}.png" alt="武装箱">`:r.kind==='gold'?`<span class="run-reward-resource"><img src="assets/ui/coin.svg" alt="金币"><b>${r.amount}</b></span>`:r.kind==='xp'?`<span class="run-reward-resource">EXP <b>${r.amount}</b></span>`:r.kind==='refresh'?`<span class="run-reward-resource">↻ <b>${r.amount}</b></span>`:'';
export function nodeScreen(game,selected=null){
 const supply=game.phase==='supply',node=getCurrentNode(game),offers=supply?game.flow?.supplyOffers||[]:game.flow?.encounterOffers||[],rerolls=supply?game.flow?.supplyRerolls:game.flow?.encounterRerolls;
 return `<div class="reference-overlay"><section class="reference-fullscreen run-node-screen ${supply?'is-supply':'is-encounter'}" role="dialog" aria-modal="true" aria-labelledby="modal-heading"><header class="reference-choice-heading"><i></i><h1 id="modal-heading">${supply?'补给阶段':'选择遭遇战'}</h1><i></i></header><p class="run-node-stage">${esc(getRunMode(game)?.name)} · ${esc(node.label)} · ${supply?'选择需要的资源，继续完善阵容':'选择对手与挑战，争取更好的战利品'}</p><div class="run-node-offers">${offers.map((o,i)=>`<button class="run-node-offer ${selected===i?'selected':''}" data-action="node-select" data-index="${i}" aria-pressed="${selected===i}"><span class="run-node-offer-icon">${supply?'▣':o.boss?'♜':'⚔'}</span>${o.level?`<small>风险等级 ${esc(o.level)}</small>`:''}<h2>${esc(o.name)}</h2><p>${esc(o.description)}</p><div class="run-node-rewards">${(o.rewards||[]).map(rewardArt).join('')}</div><span class="run-node-check">${selected===i?'✓ 已选择':'选择此项'}</span></button>`).join('')}</div><div class="run-node-actions">${supply?`<button class="run-reroll" data-action="reroll-supply" ${!rerolls?'disabled':''}>↻ 刷新 · 剩余 ${rerolls||0} 次</button>`:''}<button class="reference-confirm-button" data-action="node-confirm" ${!Number.isInteger(selected)||!offers[selected]?'disabled':''}>${supply?'确认补给':'确认挑战'}</button></div><span class="reference-screen-signature">经典回响 · ${node.label}</span></section></div>`;
}
export function routeSummary(game){const node=getCurrentNode(game),nodes=getRunNodes(game);return `${getRunMode(game)?.name||'经典远征'} · ${node.label} · ${Math.min(game.round,getRunLength(game))}/${nodes.length} 节点`;}
